export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);
  const t = time;

  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = apexHeight;
  let gateOpen = false;

  if (t >= apexTime) {
    gateOpen = true;
    const dt = t - apexTime;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
  }

  let tossState = "At launch";
  if (t > 0 && t < apexTime - 0.01) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.01) tossState = "At the top";
  else if (t > apexTime && tossedHeight > 0) tossState = "Falling";
  else if (t >= apexTime && tossedHeight <= 0) tossState = "At launch height";

  let dropState = "Held in place";
  if (t > apexTime && t < apexTime + 0.01) dropState = "Just released";
  else if (t >= apexTime + 0.01 && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0) dropState = "At launch height";

  const heightToY = (h) => 340 - (h / 2.2) * 240;
  const yToss = heightToY(Math.max(0, tossedHeight));
  const yDrop = heightToY(Math.max(0, dropHeight));

  const objects = [];
  objects.push(...sdk.panel({ x: 30, y: 50, w: 270, h: 320, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 270, h: 320, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.circle("ball.toss", 165, yToss, 26, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 475, yDrop, 26, { role: "output" }));

  objects.push(sdk.gate("gate", 475, heightToY(apexHeight), { open: gateOpen, w: 40, label: "Apex gate" }));

  objects.push(...sdk.vector("vec.v.toss", { x: 135, y: yToss }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: 195, y: yToss }, { value: tossedAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: 445, y: yDrop }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: 505, y: yDrop }, { value: dropAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.callout(75, yToss - 20, [`v: ${sdk.format(tossedVelocity)} m/s`, `a: ${sdk.format(tossedAcceleration)} m/s²`], { id: "callout.toss" }));
  objects.push(...sdk.callout(385, yDrop - 20, [`v: ${sdk.format(dropVelocity)} m/s`, `a: ${sdk.format(dropAcceleration)} m/s²`], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
